// Multiplication by a power of two can become a shift.
input x;
let y = x * 8;
let z = y + 3;
print z;

// All passes have useful work; reassignment creates a new SSA value.
input x;
input y;
let a = x + y;
let b = x + y;
let unused = (a * 16) + 99;
let result = (a * b) + (x * 8);
